// 05 Aggregate Business Metrics (Pure deterministic calculations)
const orders = $('02 Get Yesterday Orders').all().map(i => i.json);
const cruises = $('03 Get Cruise Capacity').all().map(i => i.json);
const promos = $('04 Get Promo Code Health').all().map(i => i.json);

const totalRevenue = orders.reduce((sum, o) => sum + (o.grandTotal || 0), 0);
const totalBookings = orders.length;
const totalPassengers = orders.reduce((sum, o) => sum + ((o.passengers && o.passengers.length) || 0), 0);
const aov = totalBookings > 0 ? totalRevenue / totalBookings : 0;

// Top booked cruise
const cruiseCountMap = {};
for (const o of orders) {
  const name = o.cruiseNameSnapshot || 'Unknown Route';
  cruiseCountMap[name] = (cruiseCountMap[name] || 0) + 1;
}
let topCruise = 'None';
let maxCount = 0;
for (const [name, count] of Object.entries(cruiseCountMap)) {
  if (count > maxCount) { topCruise = name; maxCount = count; }
}

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    totalRevenue: Math.round((totalRevenue + Number.EPSILON) * 100) / 100,
    totalBookings,
    totalPassengers,
    averageOrderValue: Math.round((aov + Number.EPSILON) * 100) / 100,
    topCruise,
    cruisesRaw: cruises,
    promosRaw: promos
  }
}];

// 06 Deterministic Business Rules Analysis
const data = $input.first().json;
const now = new Date();
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

// Capacity Alerts (threshold <= 2)
const capacityAlerts = data.cruisesRaw
  .filter(c => c.capacityLeft <= 2)
  .map(c => ({
    cruise: `${c.cruiseLine} — ${c.ship}`,
    capacityLeft: c.capacityLeft,
    status: c.capacityLeft === 0 ? 'SOLD_OUT' : 'CRITICAL_LOW'
  }));

// Promo Alerts (burn rate >= 80% or expiry <= 7 days)
const promoAlerts = data.promosRaw
  .filter(p => {
    const usagePct = (p.currentTotalUses / p.maxTotalUses) * 100;
    const expiryMs = new Date(p.validTo) - now;
    return usagePct >= 80 || (expiryMs > 0 && expiryMs <= SEVEN_DAYS_MS);
  })
  .map(p => ({
    code: p.code,
    usagePercentage: Math.round((p.currentTotalUses / p.maxTotalUses) * 100),
    currentUses: p.currentTotalUses,
    maxUses: p.maxTotalUses,
    validTo: p.validTo,
    isNearLimit: (p.currentTotalUses / p.maxTotalUses) >= 0.8,
    isExpiringSoon: (new Date(p.validTo) - now) <= SEVEN_DAYS_MS
  }));

return [{
  json: {
    date: data.date,
    performance: {
      revenue: data.totalRevenue,
      bookings: data.totalBookings,
      passengers: data.totalPassengers,
      averageOrderValue: data.averageOrderValue,
      topCruise: data.topCruise
    },
    capacityAlerts,
    promoAlerts
  }
}];

