const aiResponse = $input.first().json.output || $input.first().json.text || '';
const prevData = $('06 Deterministic Business Analysis').first().json;

const isValid = aiResponse && aiResponse.length > 50;

const safeInsights = isValid ? aiResponse : `Rule-based Summary: Yesterday achieved $${prevData.performance.revenue} across ${prevData.performance.bookings} bookings. ${prevData.capacityAlerts.length} capacity bottlenecks identified.`;

return [{
  json: {
    ...prevData,
    aiInsights: safeInsights,
    isValidAiResponse: isValid
  }
}];
